  "cultural_and_linguistic_notes": [
    {
      "id": 1,
      "text": "Ve španělštině se nepřeje pouze dobrý den, dobré odpoledne nebo dobrou noc, nýbrž dobré dny, dobrá odpoledne a dobré noci: Buenos días (dobrý den, dobré jitro – říká se pouze ráno a dopoledne, nikoli celý den). Po obědě je třeba použít Buenas tardes a teprve po setmění Buenas noches (dobrý večer, dobrou noc). Odpovědi na tyto pozdravy jsou buď stejné, nebo pouhé Muy buenos, popř. Muy buenas."
    },
    {
      "id": 2,
      "text": "Příjmení mužů a žen jsou stejná, nemění mužský rod v ženský: Díaz označuje pana Díaze i paní Díazovou."
    },
    {
      "id": 3,
      "text": "Adiós lze říci při setkání i při loučení. Naopak hola pouze při setkání."
    },
    {
      "id": 4,
      "text": "Salud (ž) je zdraví: Tengo buena salud. Jako pozdravu se ho používá poměrně málo, spíše se objevuje v přípitku: ¡Salud! (Na zdraví!)."
    }
  ],
  "grammar": [
    {
      "roman_numeral": "I",
      "title": "Dvojhlásky a trojhlásky",
      "page_new": 29,
      "content": {
        "vowel_classification": {
          "strong": ["A", "E", "O"],
          "weak": ["I", "U"]
        },
        "rules": [
          {
            "rule": "Dvě silné samohlásky tvoří dvě samostatné slabiky: tak se vyslovují, dělí a počítají i pro kladení či označení přízvuku.",
            "examples": ["ca-ca-o", "Ra-fa-el", "Bil-ba-o"]
          },
          {
            "rule": "Silné samohlásky (a, e, o) se slabou (i, u) tvoří dvojhlásku a jednu slabiku. Je-li na této slabice přízvuk, vysloví se přízvučně samohláska silná.",
            "examples": ["tie-ne", "tiem-po", "Juan", "bue-no", "Ma-nuel"]
          },
          {
            "rule": "Má-li být přízvuk na samohlásce slabé, musí se označit čárkou.",
            "examples": ["dí-a", "Ma-rí-a", "frí-o", "fi-lo-so-fí-a", "con-ti-nú-a"]
          },
          {
            "rule": "Dvě slabé samohlásky (iu, ui) tvoří rovněž dvojhlásku. Přízvuk je na druhé samohlásce.",
            "examples": ["Luis", "rui-na"]
          },
          {
            "rule": "Trojhlásky vznikají spojením tří samohlásek: slabé, silné a slabé. Přirozený přízvuk je opět na silné samohlásce.",
            "examples": ["lim-piáis", "con-ti-nuáis"]
          },
          {
            "rule": "Samohláska -u-, vkládaná za g- nebo q- pouze pro zachování výslovnosti předchozí hlásky, se nevyslovuje, a proto také netvoří dvojhlásku ani trojhlásku.",
            "examples": ["gui-ta-rra", "ar-qui-tec-to"]
          }
        ]
      }
    },
    {
      "roman_numeral": "II",
      "title": "Vykřičník a otazník",
      "page_new": 30,
      "content": {
        "rule": "Vykřičníky a otazníky se píší nejen za zvoláním nebo otázkou, ale i před nimi, a to obráceně:",
        "examples": [
          { "es": "¡Juan!", "cs": "Jene!" },
          { "es": "¿Tienes teléfono?", "cs": "Máš telefon?" }
        ]
      }
    },
    {
      "roman_numeral": "III",
      "title": "Zápor",
      "page_new": 30,
      "content": {
        "rule": "Záporka 'no' stojí jako samostatné slovo před časovaným tvarem slovesným (v češtině se 'ne' se slovesem spojuje v jedno slovo!):",
        "examples": [
          { "affirmative": "tengo", "affirmative_cs": "mám", "negative": "no tengo", "negative_cs": "nemám" }
        ]
      }
    },
    {
      "roman_numeral": "IV",
      "title": "Otázka",
      "page_new": 30,
      "content": {
        "rule": "Otázka se tvoří převrácením slovosledu, případně změnou intonace:",
        "examples": [
          { "statement": "Juan tiene tiempo.", "statement_cs": "Jan má čas.", "question": "¿Tiene Juan tiempo?", "question_cs": "Má Jan čas?" },
          { "statement": "Manuel no tiene dinero.", "statement_cs": "Manuel nemá peníze.", "question": "¿No tiene Manuel dinero?", "question_cs": "Nemá Manuel peníze?" },
          { "statement": "Intonací beze změny slovosledu:", "statement_cs": "Podobně jako v češtině:", "question": "¿Manolo no tiene dinero?", "question_cs": "Manolo nemá peníze?" }
        ]
      }
    }
  ],
