    {
      "roman_numeral": "I",
      "title": "Rod (Podstatná jména)",
      "page_new": 34,
      "content": {
        "rules": [
          {
            "rule": "Španělská podstatná jména jsou rodu mužského nebo ženského (nejsou tedy středního rodu jako v češtině). Jména mužských bytostí jsou přirozeně rodu mužského, jména ženských bytostí jsou rodu ženského.",
            "examples": [
              { "m": "Juan", "f": "Eva" },
              { "m": "el señor", "f": "la señora" },
              { "m": "el alumno", "f": "la alumna" }
            ]
          },
          {
            "rule": "Jména končící na -o, -or bývají rodu mužského.",
            "examples": ["el cacao", "el trabajo", "el teléfono", "el tiempo", "el calor"]
          },
          {
            "rule": "Jména končící na -a, -ión bývají rodu ženského.",
            "examples": ["la mesa", "la revolución"]
          },
          {
            "rule": "Výjimky z pravidla o koncovkách: podstatná jména řeckého původu na -ma a další.",
            "examples": [
              { "word": "el problema", "cs": "problém (m)" },
              { "word": "el telegrama", "cs": "telegram (m)" },
              { "word": "el tema", "cs": "téma (m)" },
              { "word": "el mapa", "cs": "mapa (m)" },
              { "word": "el día", "cs": "den (m)" },
              { "word": "la radio", "cs": "rádio (ž)" }
            ]
          },
          {
            "rule": "U jmen s jinými koncovkami je třeba si rod pamatovat.",
            "examples": ["el pan", "el chocolate", "la tarde", "la noche"]
          },
          {
            "rule": "Některá jména mají týž tvar pro mužský i ženský rod. Rod se pozná podle členu, přídavného jména nebo podle smyslu.",
            "examples": [
              { "es": "un pianista inteligente", "cs": "jeden inteligentní klavírista" },
              { "es": "una pianista inteligente", "cs": "jedna inteligentní klavíristka" }
            ]
          }
        ]
      }
    },
    {
      "roman_numeral": "II",
      "title": "Člen a Přídavná jména",
      "page_new": 35,
      "content": {
        "adjectives": {
          "rules": [
            {
              "rule": "Přídavná jména se shodují v rodě i čísle s podstatným jménem, které doprovázejí. Mají-li v mužském rodě koncové -o, končí v ženském rodě na -a.",
              "examples": ["bueno (dobrý) – buena (dobrá)"]
            },
            {
              "rule": "Mají-li v mužském rodě koncové -e, -a, pak se v ženském rodě většinou nemění.",
              "examples": ["inteligente", "interesante", "grande", "belga"]
            },
            {
              "rule": "Ve většině případů se klade přídavné jméno ZA podstatné jméno.",
              "examples": ["un diccionario español–checo y checo–español"]
            }
          ]
        },
        "articles": {
          "table": {
            "masculine": { "definite": "el amigo", "indefinite": "un amigo" },
            "feminine": { "definite": "la amiga", "indefinite": "una amiga" }
          },
          "usage": [
            {
              "type": "indefinite",
              "rule": "Zmiňujeme-li se o někom nebo o něčem poprvé, použijeme členu neurčitého un, una; má zároveň význam jeden, jedna, nějaký, nějaká.",
              "example": "Es un vino español."
            },
            {
              "type": "definite",
              "rule": "Mluvíme-li o určité osobě nebo věci, známé třeba jen z předešlé věty, použijeme členu určitého el, la, který zároveň znamená ten, ta.",
              "example": "Es el vino málaga."
            }
          ],
          "zero_article": [
            {
              "condition": "U většiny vlastních jmen",
              "examples": ["Manuel", "Lola", "Madrid", "Cuba"]
            },
            {
              "condition": "Při oslovení a ve zvolání (5. pád v češtině)",
              "examples": [
                { "with_article": "el señor Blanco", "cs_with": "pan Blanco" },
                { "vocative": "¡Señor Blanco!", "cs_voc": "Pane Blanco!" }
              ]
            }
          ],
          "substantivization": {
            "rule": "Členem se zpodstatňují jiné druhy slov:",
            "examples": [
              { "base": "español (španělský)", "substantivized": "el n. un español (Španěl)" },
              { "base": "frío (studený)", "substantivized": "el n. un frío (chladno, zima)" },
              { "base": "uno (jeden)", "substantivized": "el n. un uno (jednička)" }
            ]
          }
        }
      }
    }
