      "content": {
        "special_forms": [
          { "base": "yo", "after_prep": "mí*", "cs": "mně, mne, mě", "example": "para mí (pro mne)" },
          { "base": "tú", "after_prep": "ti", "cs": "tobě, tebe, tě", "example": "sin ti (bez tebe)" },
          { "base": "se (zvratné)", "after_prep": "sí*", "cs": "sobě, sebe", "example": "para sí (pro sebe)" }
        ],
        "invariable_forms": {
          "rule": "Ostatní zájmena mají po předložkách stejný tvar jako v 1. pádě:",
          "examples": [
            { "es": "una carta para él", "cs": "dopis pro něho" },
            { "es": "hablan de nosotros", "cs": "mluví o nás" },
            { "es": "un regalo para vosotros", "cs": "dárek pro vás" }
          ]
        },
        "entre_rule": {
          "rule": "Po předložce entre (mezi) se používají tvary 1. pádu yo, tú (nikoli mí, ti):",
          "example": { "es": "Entre tú y yo no hay problemas.", "cs": "Mezi tebou a mnou nejsou problémy." },
          "reflexive_with_entre": "Zvratné zájmeno se po entre mění na sí: Discuten entre sí (Diskutují mezi sebou)."
        },
        "con_combinations": {
          "rule": "S předložkou con se tvary mí, ti, sí spojují do zvláštních slov:",
          "forms": [
            { "combination": "con + mí", "result": "conmigo", "cs": "se mnou" },
            { "combination": "con + ti", "result": "contigo", "cs": "s tebou" },
            { "combination": "con + sí", "result": "consigo", "cs": "se sebou" }
          ]
        },
        "reflexive_usage_rule": {
          "rule": "Zvratná zájmena (sí, consigo) se užívají výhradně ve 3. osobě. V ostatních osobách se použije tvar příslušné osoby:",
          "table": [
            { "person": "yo", "es": "Llevo conmigo a mi hijo.", "cs": "Vezu s sebou svého syna." },
            { "person": "tú", "es": "Llevas contigo a tu hijo.", "cs": "Vezeš s sebou svého syna." },
            { "person": "él", "es": "Lleva consigo a su hijo.", "cs": "Veze s sebou svého syna." },
            { "person": "nosotros", "es": "Llevamos con nosotros a nuestro hijo.", "cs": "Vezeme s sebou svého syna." },
            { "person": "vosotros", "es": "Lleváis con vosotros a vuestro hijo.", "cs": "Vezete s sebou svého syna." },
            { "person": "ellos", "es": "Llevan consigo a su hijo.", "cs": "Vezou s sebou svého syna." }
          ]
        },
        "emphasis_reduplication": {
          "rule": "K zdůraznění nebo rozlišení se samostatné zájmeno klade na začátek věty společně s nesamostatným tvarem:",
          "examples": [
            { "es": "Me gusta. ¿A ti no te gusta?", "cs": "Líbí se mi to. Tobě se to nelíbí?" },
            { "es": "– Sí, a mí me gusta también.", "cs": "– Ano, mně se to také líbí." }
          ]
        }
      }
