// Pomocná funkce pro získání konkrétní lekce
export function getProkopovaLessonData(lessonNumber: number): ProkopovaLesson | undefined {
  // Propojení s databází lekcí
  return (PROKOPOVA_BOOK_DATA as any).lessons?.find(
    (l: ProkopovaLesson) => l.lesson_number === lessonNumber
  );
}

// Převod identifikátoru stopy (např. "oddil_1_track_07") na název MP3 souboru ("1_07.mp3")
export function resolveAudioTrackFile(trackId: string): string {
  const match1 = trackId.match(/oddil_1_track_(\d+)/);
  if (match1) {
    return `1_${match1[1].padStart(2, '0')}.mp3`;
  }
  const match2 = trackId.match(/oddil_2_track_(\d+)/);
  if (match2) {
    return `2_${match2[1].padStart(2, '0')}.mp3`;
  }
  return trackId;
}